/**
 * BridgeMind Database Expansion v4
 * 
 * Adds ~550 NEW UNIQUE peer-reviewed research papers across all 26 domains,
 * with heavy focus on underrepresented domains (Transportation, Aviation,
 * Climate, Agriculture, Mechanical Eng, Chemical Eng, Education, Aerospace).
 *
 * Triple deduplication: normalized title, paper ID, and URL.
 * Rebuilds FTS5 index, updates dataset-stats.json and case-studies.json.
 *
 * Run: node scripts/expand-database-v4.js
 */

const Database = require("better-sqlite3");
const fs = require("fs");
const path = require("path");

const DB_PATH = path.join(__dirname, "..", "src", "data", "analogy_engine.db");
const STATS_PATH = path.join(__dirname, "..", "src", "data", "dataset-stats.json");
const CASE_STUDIES_PATH = path.join(__dirname, "..", "src", "data", "case-studies.json");

const db = new Database(DB_PATH);
db.pragma("journal_mode = WAL");
db.pragma("synchronous = NORMAL");

function normalizeTitle(t) {
  return (t || "").toLowerCase().trim().replace(/[^a-z0-9]/g, "");
}

// ═══════════════════════════════════════════════════════════
//  PHASE 0: Snapshot existing database state
// ═══════════════════════════════════════════════════════════

const existingCount = db.prepare("SELECT COUNT(*) as c FROM case_studies").get().c;
const existingIds = new Set(db.prepare("SELECT id FROM case_studies").all().map(r => r.id));
const existingNormTitles = new Set(db.prepare("SELECT title FROM case_studies").all().map(r => normalizeTitle(r.title)));
const existingUrls = new Set(
  db.prepare("SELECT url FROM case_studies WHERE url IS NOT NULL AND url != ''").all().map(r => r.url.trim().toLowerCase())
);

console.log(`\n╔══════════════════════════════════════════════════════════╗`);
console.log(`║  BridgeMind Database Expansion v4                        ║`);
console.log(`║  Current papers in SQLite: ${existingCount}                         ║`);
console.log(`║  Existing unique title hashes: ${existingNormTitles.size}                    ║`);
console.log(`║  Existing unique URLs: ${existingUrls.size}                              ║`);
console.log(`╚══════════════════════════════════════════════════════════╝\n`);

